using System;
using System.IO;
using System.Collections.Generic;
using System.Windows.Forms;
namespace Downfield {
public static partial class UiTests {
 static void PlaybookUpdateScreens(GameForm f,string evidence){Set(f,"matchFixture",-1);Franchise club=Franchise.Create(new Profile(),new Roster());Set(f,"franchise",club);Set(f,"screen","franchisehub");Set(f,"selection",1);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="teamhub","franchise Team opens a focused management section");f.SavePreview(Path.Combine(evidence,"team-hub.png"));Set(f,"selection",3);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="stadium","money lives under Team");Tap(f,Keys.Escape);Check((string)Get(f,"screen")=="teamhub","money back returns to Team");Set(f,"selection",1);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="transfershub","signing trading and draft grouped together");f.SavePreview(Path.Combine(evidence,"transfers-hub.png"));Tap(f,Keys.Escape);Tap(f,Keys.Escape);Check((string)Get(f,"screen")=="franchisehub","nested back returns to franchise office");Set(f,"selection",2);Call(f,"ActivateSelection");f.SavePreview(Path.Combine(evidence,"league-hub.png"));Check((string)Get(f,"screen")=="leaguehub","league records and competitions have one section");
  Set(f,"screen","settings");Set(f,"selection",2);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="bindings","options opens remapping page");Set(f,"selection",12);Call(f,"ActivateSelection");typeof(GameForm).GetMethod("CaptureControlKey",flags).Invoke(f,new object[]{Keys.G});Input input=(Input)Get(f,"input");Check(input.Bindings.Key(11)==Keys.G&&!((bool)Get(f,"capturing")),"keyboard binding captures chosen key");f.SavePreview(Path.Combine(evidence,"keyboard-bindings.png"));Set(f,"selection",0);Call(f,"ActivateSelection");f.SavePreview(Path.Combine(evidence,"controller-bindings.png"));Check((bool)Get(f,"controllerBindings"),"controller has its own binding page");input.Bindings=new ControlBindings();input.Bindings.Save();Set(f,"capturing",false);Set(f,"controllerBindings",false);input.Clear();
  Call(f,"StartPractice");Simulation s=(Simulation)Get(f,"game");Call(f,"OpenDesigner");typeof(GameForm).GetMethod("DesignerAction",flags).Invoke(f,new object[]{8});Check(club.PlayLibrary.Count==1,"designer Save to Book adds a callable play");typeof(GameForm).GetMethod("DesignerAction",flags).Invoke(f,new object[]{12});Set(f,"playNameDraft","BANANA SPLIT");Set(f,"selection",38);Call(f,"ActivateSelection");Check(club.PlayLibrary[0].Name=="BANANA SPLIT"&&(string)Get(f,"screen")=="designer","play can be named using saved-play editor");Call(f,"ApplyDraft");Tap(f,Keys.Y);Set(f,"selection",s.PlayNames.Length);f.SavePreview(Path.Combine(evidence,"saved-playbook.png"));Tap(f,Keys.Enter);Check(s.UseCustom&&s.CustomPlay.Name=="BANANA SPLIT","named custom route called through playbook");Tap(f,Keys.Space);Step(f,Keys.None,false,15);Tap(f,Keys.D1);Check(s.State==Phase.Flight&&!s.CatchMeterActive,"ordinary throw starts with normal catching");Tap(f,Keys.Y);Check(s.CatchMeterActive&&!s.CatchMeterLocked,"Y starts aggressive catch during flight");s.CatchMeterValue=.5f;Tap(f,Keys.Y);Check(s.CatchMeterLocked&&s.CatchGrade=="GREEN","second Y locks green timing");f.SavePreview(Path.Combine(evidence,"catch-meter.png"));for(int n=0;n<70&&s.State==Phase.Flight;n++)Step(f,Keys.None,false,1);Check(s.Completions==1,"green timing catches through actual gameplay input");
  foreach(ClubPlayer p in club.Squad(club.UserTeam))if(p.Role=="QB")p.InjuryWeeks=3;Call(f,"StartPractice");s=(Simulation)Get(f,"game");Step(f,Keys.None,false,1);Check((string)Get(f,"screen")=="emergencyqb","injured quarterbacks open roster selection before snap");f.SavePreview(Path.Combine(evidence,"emergency-qb.png"));List<ClubPlayer> options=s.EmergencyCandidates();int chosen=options.FindIndex(p=>p.Role=="CB");Set(f,"selection",chosen);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="game"&&s.Controlled.ClubId==options[chosen].Id,"healthy defensive player can take emergency snaps");
  foreach(ClubPlayer p in club.Squad(club.UserTeam))p.InjuryWeeks=0;Call(f,"StartGame");s=(Simulation)Get(f,"game");Set(f,"screen","pause");Set(f,"selection",8);Tap(f,Keys.Enter);Check(s.Timeouts==2&&(string)Get(f,"screen")=="game","pause timeout uses one of three half timeouts");f.SavePreview(Path.Combine(evidence,"timeout-count.png"));s.CallPlay(32);Tap(f,Keys.Y);Set(f,"selection",30);f.SavePreview(Path.Combine(evidence,"trick-playbook.png"));Set(f,"screen","trade");Set(f,"selection",0);Call(f,"ActivateSelection");Set(f,"selection",0);Call(f,"ActivateSelection");List<ClubPlayer> targets=(List<ClubPlayer>)typeof(GameForm).GetMethod("FrontPlayers",flags).Invoke(f,null);Check(targets.Exists(p=>p.Role=="RB")&&targets.Exists(p=>p.Role=="DL"),"trade targets include every position");f.SavePreview(Path.Combine(evidence,"cross-position-trades.png"));Set(f,"matchFixture",-1);Set(f,"screen","home");
 }
}
